type schProof struct{Path,Hash string;Stop flowStop}
func schSync(dir string)error{f,e:=os.Open(dir);if e!=nil{return e};defer f.Close();return f.Sync()}
func schWrite(path string,v any)error{if e:=scpWrite(path,v);e!=nil{return e};return schSync(filepath.Dir(path))}
func schBinding(root string)([]byte,map[string]any,map[string]any,error){b,e:=os.ReadFile(filepath.Join(root,"source-evidence.private.json"));if e!=nil{return nil,nil,nil,e};var binding map[string]any;if e=json.Unmarshal(b,&binding);e!=nil{return nil,nil,nil,e};path,ok:=binding["raw_path"].(string);if !ok{return nil,nil,nil,fmt.Errorf("raw path type")};rb,e:=os.ReadFile(path);if e!=nil{return nil,nil,nil,e};if binding["source"]!=scpSource||binding["raw_sha256"]!=scpHash(rb){return nil,nil,nil,fmt.Errorf("source binding mismatch")};var raw map[string]any;if e=json.Unmarshal(rb,&raw);e!=nil{return nil,nil,nil,e};if raw["source"]!=scpSource||raw["readonly"]!="on"||raw["assigned_xid"]!=nil{return nil,nil,nil,fmt.Errorf("source controls mismatch")};chs,ok:=raw["channels"].([]any);if !ok||len(chs)<44{return nil,nil,nil,fmt.Errorf("retained channels missing")};return b,binding,raw,nil}
func schArgs(q []*scpQuery,wire []*scpWire,addr string)error{if len(q)!=len(wire){return fmt.Errorf("driver wire query count")};for i,x:=range q{w:=wire[i];if x.SQL!=w.SQL||w.Error!=""||w.End.IsZero(){return fmt.Errorf("wire identity or completion")};args:=w.Args;if len(args)==len(x.Args)+1{if _,ok:=args[0].(pgx.QueryResultFormatsByOID);!ok{return fmt.Errorf("wire option type")};args=args[1:]};if len(args)!=len(x.Args){return fmt.Errorf("wire argument count")};for j,a:=range x.Args{if !reflect.DeepEqual(a.Value,args[j]){return fmt.Errorf("wire argument differs")}};if w.Tag!="SELECT "+strconv.Itoa(len(x.Rows)){return fmt.Errorf("wire returned row count differs")}}
 if len(q)==0{return nil};memo:=q[0];if memo.DrainedRows!=0||len(memo.Args)!=2||memo.Args[0].Value!=addr||fmt.Sprint(memo.Args[1].Value)!=strconv.Itoa(flowMemoSample){return fmt.Errorf("actual memo arguments or consumed rows differ")};if len(q)==2{a:=q[1].Args;if len(a)!=6{return fmt.Errorf("count argument count")};for _,i:=range []int{0,1,3,4}{if a[i].Value!=addr{return fmt.Errorf("count address argument")}};for _,i:=range []int{2,5}{if fmt.Sprint(a[i].Value)!=strconv.Itoa(ledgerHeavyRows+1){return fmt.Errorf("count limit argument")}}};return nil}
func schGuardOld(pids []int)error{for _,pid:=range pids{e:=syscall.Kill(pid,0);if e!=syscall.ESRCH{return fmt.Errorf("previous owned supplier still exists")}};return nil}
