 requestStart:=len(s.rec.Queries);s.rec.Phase="before_stop_controls";before,e:=scpReadControls(s.tx);if e!=nil||before!=s.c{return fmt.Errorf("before stop identity")};cached,exists:=cache[addr];var proof schProof
